/// Motor de las aplicaciones de Electron: corre en la ventana (el proceso
/// de render, con Node), pinta los componentes con React y los ofrece al
/// código del usuario como objetos con propiedades, al estilo de Delphi:
/// `this.Label1.text = "Hola"` vuelve a pintar la ventana.
const tkElectronRuntimeJs = r'''"use strict";
// Generated by DMarlon Studio. Do not edit.
// Lo que depende de dónde corre (Electron o una extensión de Chrome) está
// en DMS_HOST (host.js).
const DMS_HOST = window.DMS_HOST;
const React = DMS_HOST.need("react");
const { createRoot } = DMS_HOST.need("react-dom/client");
const h = React.createElement;

/** Lo que trae un enlace o un formulario de una Vista HTML. */
class HtmlAction {
  constructor(name, arg, form) {
    this.name = name;
    this.arg = arg || "";
    this.form = form || {};
  }
  get(key, fallback = "") {
    const v = this.form[key];
    if (v === undefined) return fallback;
    return Array.isArray(v) ? v[v.length - 1] : v;
  }
}

/** Un evento del ratón o del teclado, con lo de tkinter y el original. */
function dmsEvent(widget, e) {
  const box = e && e.currentTarget && e.currentTarget.getBoundingClientRect
    ? e.currentTarget.getBoundingClientRect() : { left: 0, top: 0 };
  return {
    widget,
    x: e && e.clientX !== undefined ? Math.round(e.clientX - box.left) : 0,
    y: e && e.clientY !== undefined ? Math.round(e.clientY - box.top) : 0,
    key: e && e.key ? e.key : "",
    char: e && e.key && e.key.length === 1 ? e.key : "",
    button: e && e.button !== undefined ? e.button + 1 : 0,
    original: e,
  };
}

const DMS_LIST = new Set(["Listbox", "Combobox"]);

/** Un componente: sus propiedades se leen y se cambian como en Delphi. */
class DmsWidget {
  constructor(form, kind, name, parent, page, box, props, events, extra) {
    this._form = form;
    this.kind = kind;
    this.name = name;
    this.parent = parent;
    this.pageIndex = page;
    [this._x, this._y, this._w, this._h] = box;
    this._p = Object.assign({}, props);
    this._events = events || {};
    this._extra = extra || {};
    this._rows = [];
    this._sel = -1;
    this._multi = [];
    this._timer = null;
    if (DMS_LIST.has(kind)) this._items = (props.items || []).slice();
    if (kind === "Combobox") this._sel = this._items.indexOf(props.text || "");
  }

  _set(key, value) {
    this._p[key] = value;
    this._form._render();
  }

  _fire(key, arg) {
    const method = this._events[key];
    if (method) return this._form._call(method, arg);
    return undefined;
  }

  /** Cambia varias propiedades a la vez: configure({ text: "Hola" }). */
  configure(options) {
    for (const [k, v] of Object.entries(options || {})) {
      if (k in this && k !== "kind" && k !== "name") this[k] = v;
      else this._p[k] = v;
    }
    this._form._render();
    return this;
  }

  cget(key) { return key in this ? this[key] : this._p[key]; }

  get x() { return this._x; }
  set x(v) { this._x = Number(v); this._form._render(); }
  get y() { return this._y; }
  set y(v) { this._y = Number(v); this._form._render(); }
  get width() { return this._w; }
  set width(v) { this._w = Number(v); this._form._render(); }
  get height() { return this._h; }
  set height(v) { this._h = Number(v); this._form._render(); }
  move(x, y) { this._x = Number(x); this._y = Number(y); this._form._render(); }
  resize(w, hgt) { this._w = Number(w); this._h = Number(hgt); this._form._render(); }

  get text() {
    if (this.kind === "Listbox") return this.selected;
    return String(this._p.text === undefined || this._p.text === null ? "" : this._p.text);
  }
  set text(v) {
    this._set("text", v === undefined || v === null ? "" : String(v));
    if (this.kind === "Combobox") this._sel = this._items.indexOf(this._p.text);
  }

  get value() {
    switch (this.kind) {
      case "Scale":
      case "Progressbar":
        return Number(this._p.value || 0);
      case "Checkbutton":
      case "Radiobutton":
        return this.checked;
      case "Listbox":
        return this.selected;
      default:
        return this.text;
    }
  }
  set value(v) {
    switch (this.kind) {
      case "Scale":
      case "Progressbar":
        this._set("value", Number(v) || 0);
        break;
      case "Checkbutton":
      case "Radiobutton":
        this.checked = v;
        break;
      case "Listbox":
        this.index = this._items.indexOf(String(v));
        break;
      default:
        this.text = v;
    }
  }

  get enabled() { return this._p.state !== "disabled" && this._p.enabled !== false; }
  set enabled(v) {
    if (this.kind === "Timer") {
      if (v) this.start(); else this.stop();
      return;
    }
    this._set("state", v ? "normal" : "disabled");
  }
  get readonly() { return this._p.state === "readonly"; }
  set readonly(v) { this._set("state", v ? "readonly" : "normal"); }
  get visible() { return this._p.visible !== false; }
  set visible(v) { this._set("visible", !!v); }
  get bg() { return this._p.bg || ""; }
  set bg(v) { this._set("bg", v); }
  get fg() { return this._p.fg || ""; }
  set fg(v) { this._set("fg", v); }

  focus() {
    const el = document.getElementById(this.name);
    const field = el && (el.matches("input,textarea,select,button") ? el : el.querySelector("input,textarea,select,button"));
    if (field) field.focus();
  }

  // ---------------------------------------------------- casillas y radios
  get checked() { return !!this._p.checked; }
  set checked(v) {
    if (this.kind === "Radiobutton" && v) {
      for (const w of this._form._widgets) {
        if (w !== this && w.kind === "Radiobutton" && w._p.group === this._p.group) w._p.checked = false;
      }
    }
    this._set("checked", !!v);
  }

  // ------------------------------------------------------- listas y combos
  get items() { return (this._items || []).slice(); }
  set items(list) {
    this._items = Array.from(list || [], String);
    this._sel = -1;
    this._multi = [];
    this._form._render();
  }
  add(item) {
    if (this.kind === "Treeview") return this.addRow(item);
    this._items.push(String(item));
    this._form._render();
    return this;
  }
  clear() {
    if (this.kind === "Treeview") this._rows = [];
    else if (this._items) this._items = [];
    else if (this.kind === "Text" || this.kind === "Entry") this._p.text = "";
    this._sel = -1;
    this._multi = [];
    this._form._render();
    return this;
  }
  remove(index) {
    const list = this.kind === "Treeview" ? this._rows : this._items;
    if (list && index >= 0 && index < list.length) list.splice(index, 1);
    if (this._sel >= (list ? list.length : 0)) this._sel = -1;
    this._form._render();
  }
  get index() { return this._sel; }
  set index(i) {
    this._sel = Number.isInteger(i) ? i : -1;
    if (this.kind === "Combobox") this._p.text = this._items[this._sel] || "";
    this._multi = this._sel >= 0 ? [this._sel] : [];
    this._form._render();
  }
  get selected() {
    if (this.kind === "Treeview") return this.selectedRow;
    return this._sel >= 0 && this._items ? this._items[this._sel] : "";
  }
  get selection() { return this._multi.slice(); }
  set selection(list) {
    this._multi = Array.from(list || []);
    this._sel = this._multi.length ? this._multi[0] : -1;
    this._form._render();
  }

  // --------------------------------------------------------------- tabla
  get columns() { return (this._extra.columns || []).slice(); }
  get rows() { return this._rows.slice(); }
  set rows(list) {
    this._rows = Array.from(list || []);
    this._sel = -1;
    this._form._render();
  }
  addRow(values) {
    this._rows.push(values);
    this._form._render();
    return this._rows.length - 1;
  }
  get selectedRow() { return this._sel >= 0 ? this._rows[this._sel] : null; }
  _cell(row, column, i) {
    if (Array.isArray(row)) return row[i];
    if (row && typeof row === "object") return row[column.field];
    return i === 0 ? row : "";
  }

  // -------------------------------------------------------------- páginas
  get page() { return Number(this._p.active || 0); }
  set page(i) {
    this._set("active", Number(i) || 0);
    this._fire("change");
  }
  get pages() { return (this._extra.pages || []).slice(); }

  // ------------------------------------------------------- vista y barra
  get html() { return this._p.html || ""; }
  set html(v) { this._set("html", String(v)); }
  setHtml(html, top = false) {
    this.html = html;
    if (top) window.scrollTo(0, 0);
  }
  get icon() { return this._p.icon || ""; }
  set icon(v) { this._set("icon", v); }
  set(text, icon) {
    this._p.text = String(text);
    if (icon !== undefined) this._p.icon = icon;
    this._form._render();
  }
  get file() { return this._p.file || ""; }
  set file(v) { this._set("file", v); }
  load(file) { this.file = file; }
  get maximum() { return Number(this._p.maximum || 100); }
  set maximum(v) { this._set("maximum", Number(v)); }

  // ------------------------------------------------ temporizador y barra
  get interval() { return Number(this._p.interval || 1000); }
  set interval(v) {
    this._p.interval = Math.max(1, Number(v) || 1000);
    if (this._timer) { this.stop(); this.start(); }
  }
  start() {
    if (this.kind === "Progressbar") { this._set("running", true); return; }
    if (this._timer) return;
    this._p.enabled = true;
    this._timer = setInterval(() => this._fire("command"), this.interval);
  }
  stop() {
    if (this.kind === "Progressbar") { this._set("running", false); return; }
    this._p.enabled = false;
    if (this._timer) clearInterval(this._timer);
    this._timer = null;
  }

  // ------------------------------------------------------------ diálogos
  /** Abre el diálogo: devuelve la ruta (o rutas), o null si se cancela. */
  async execute() {
    const options = Object.assign({}, this._p, { filters: this._extra.filters || [] });
    const kind = this.kind === "SaveDialog" ? "save" : "open";
    const result = await DMS_HOST.dialog(kind, options);
    if (result !== null && result !== undefined) this._fire("select", result);
    return result;
  }
  readText(file) { return DMS_HOST.readText(file); }
  writeText(file, text) { return DMS_HOST.writeText(file, String(text)); }
}

/** La ventana: el FormDesign generado hereda de aquí. */
class DmsForm {
  constructor(options) {
    this._options = options;
    this._widgets = [];
    this._formEvents = {};
    this._queued = false;
    this._listener = null;
    this._title = options.title || "";
    this._bg = options.bg || "#f0f0f0";
    this._toast = "";
    document.title = this._title;
  }

  _add(kind, name, parent, page, box, props, events, extra) {
    const w = new DmsWidget(this, kind, name, parent, page, box, props, events, extra);
    this._widgets.push(w);
    this[name] = w;
    return w;
  }

  _render() {
    if (this._queued) return;
    this._queued = true;
    queueMicrotask(() => {
      this._queued = false;
      if (this._listener) this._listener();
    });
  }

  _call(method, ...args) {
    const fn = this[method];
    if (typeof fn !== "function") return undefined;
    try {
      const result = fn.apply(this, args);
      if (result && typeof result.catch === "function") {
        result.catch((error) => console.error(error && error.stack ? error.stack : error));
      }
      return result;
    } catch (error) {
      console.error(error && error.stack ? error.stack : String(error));
      return undefined;
    }
  }

  get title() { return this._title; }
  set title(v) {
    this._title = String(v);
    document.title = this._title;
  }
  get bg() { return this._bg; }
  set bg(v) { this._bg = v; this._render(); }
  get width() { return this._options.width; }
  get height() { return this._options.height; }

  /** Un mensaje en un diálogo. */
  message(text, title) { DMS_HOST.alert(String(text), title); }
  /** Una pregunta de sí o no: true o false. */
  ask(question) { return confirm(String(question)); }
  /** Un aviso que se va solo. */
  notify(text) {
    this._toast = String(text);
    this._render();
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => { this._toast = ""; this._render(); }, 3000);
  }
  /** Llama a fn dentro de ms milisegundos. */
  after(ms, fn, ...args) { return setTimeout(() => this._callFn(fn, args), ms); }
  _callFn(fn, args) {
    try { fn.apply(this, args); } catch (error) { console.error(error && error.stack ? error.stack : error); }
  }
  close() { window.close(); }

  // ----------------------------------- extensiones (y vista previa)
  /** Datos que se guardan: await this.storage.get(clave, siNoHay). */
  get storage() { return DMS_HOST.storage; }
  /** La pestaña activa: { id, url, title }. */
  currentTab() { return DMS_HOST.currentTab(); }
  /** Abre una dirección en una pestaña nueva. */
  openTab(url) { return DMS_HOST.openTab(String(url)); }
  /** Ejecuta fn en la página de la pestaña activa y devuelve su resultado. */
  runInPage(fn, ...args) { return DMS_HOST.runInPage(fn, ...args); }
  /** El texto (y el color) de la insignia del icono de la extensión. */
  badge(text, color) { return DMS_HOST.badge(text, color); }
  get widgets() { return this._widgets.slice(); }
}

// --------------------------------------------------------------- pintar
function dmsStyle(w, extra) {
  const p = w._p;
  const s = { left: w._x, top: w._y, width: w._w, height: w._h };
  if (p.bg) s.background = p.bg;
  if (p.fg) s.color = p.fg;
  if (p.font_family) s.fontFamily = p.font_family;
  if (p.font_size) s.fontSize = p.font_size + "px";
  if (p.font_bold) s.fontWeight = "bold";
  if (p.font_italic) s.fontStyle = "italic";
  const relief = { raised: "2px outset #c8c8c8", sunken: "2px inset #c8c8c8", groove: "2px groove #c8c8c8", ridge: "2px ridge #c8c8c8", solid: "1px solid #6e7480" };
  if (p.relief && relief[p.relief]) s.border = relief[p.relief];
  if (p.visible === false) s.display = "none";
  return Object.assign(s, extra || {});
}

function dmsMouse(w) {
  const on = {};
  const ev = w._events;
  if (ev.click) on.onMouseDown = (e) => w._fire("click", dmsEvent(w, e));
  if (ev.double) on.onDoubleClick = (e) => w._fire("double", dmsEvent(w, e));
  if (ev.right) on.onContextMenu = (e) => { e.preventDefault(); w._fire("right", dmsEvent(w, e)); };
  if (ev.enter) on.onMouseEnter = (e) => w._fire("enter", dmsEvent(w, e));
  if (ev.leave) on.onMouseLeave = (e) => w._fire("leave", dmsEvent(w, e));
  return on;
}

function dmsKeys(w) {
  return {
    onKeyDown: (e) => {
      if (e.key === "Enter" && w.kind !== "Text") w._fire("enter_key", dmsEvent(w, e));
      w._fire("key", dmsEvent(w, e));
    },
    onKeyUp: (e) => w._fire("key_up", dmsEvent(w, e)),
    onFocus: (e) => w._fire("focus_in", dmsEvent(w, e)),
    onBlur: (e) => w._fire("focus_out", dmsEvent(w, e)),
  };
}

const DMS_ANCHOR = {
  w: ["flex-start", "center"], e: ["flex-end", "center"], n: ["center", "flex-start"],
  s: ["center", "flex-end"], center: ["center", "center"],
};

function DmsPassword({ w }) {
  const [shown, setShown] = React.useState(false);
  const p = w._p;
  return h("div", Object.assign({ id: w.name, className: "tk tk-pass", style: dmsStyle(w) }, dmsMouse(w)),
    h("input", Object.assign({
      type: shown ? "text" : "password", value: w.text, placeholder: p.hint || "",
      maxLength: p.maxlength > 0 ? p.maxlength : undefined,
      disabled: p.state === "disabled", readOnly: p.state === "readonly",
      onChange: (e) => { w._p.text = e.target.value; w._form._render(); },
    }, dmsKeys(w))),
    p.reveal !== false ? h("button", { type: "button", className: "tk-eye", tabIndex: -1, onClick: () => setShown(!shown) }, shown ? "○" : "◉") : null);
}

function dmsHtmlClick(w, e) {
  const el = e.target.closest("[data-action]");
  if (!el || el.tagName === "FORM") return;
  e.preventDefault();
  w._fire("action", new HtmlAction(el.dataset.action, el.dataset.arg));
}

function dmsHtmlSubmit(w, e) {
  const formEl = e.target;
  if (!formEl.dataset || !formEl.dataset.action) return;
  e.preventDefault();
  const fields = {};
  new FormData(formEl).forEach((v, k) => {
    if (typeof v !== "string") return;
    fields[k] = k in fields ? [].concat(fields[k], v) : v;
  });
  w._fire("action", new HtmlAction(formEl.dataset.action, formEl.dataset.arg, fields));
}

function dmsChildren(form, parent, page) {
  return form._widgets
    .filter((c) => c.parent === parent && (page === undefined || c.pageIndex === page))
    .map((c) => dmsWidget(c));
}

function dmsWidget(w) {
  const p = w._p;
  const key = w.name;
  const base = Object.assign({ key, id: w.name }, dmsMouse(w));
  switch (w.kind) {
    case "Label": {
      const [jc, ai] = DMS_ANCHOR[p.anchor] || DMS_ANCHOR.center;
      const extra = { justifyContent: jc, alignItems: ai, textAlign: p.justify || "center" };
      if (p.wraplength > 0) Object.assign(extra, { whiteSpace: "pre-wrap" });
      return h("div", Object.assign(base, { className: "tk tk-label", style: dmsStyle(w, extra) }), w.text);
    }
    case "Button":
      return h("button", Object.assign(base, {
        className: "tk", style: dmsStyle(w), disabled: !w.enabled,
        onClick: () => w._fire("command"),
      }), w.text);
    case "Entry":
      return h("input", Object.assign(base, dmsKeys(w), {
        className: "tk", style: dmsStyle(w, { textAlign: p.justify || undefined }),
        type: p.show ? "password" : "text", value: w.text,
        disabled: p.state === "disabled", readOnly: p.state === "readonly",
        onChange: (e) => { w._p.text = e.target.value; w._form._render(); },
      }));
    case "Password":
      return h(DmsPassword, { key, w });
    case "Text":
      return h("textarea", Object.assign(base, dmsKeys(w), {
        className: "tk", style: dmsStyle(w, p.wrap === "none" ? { whiteSpace: "pre", overflowWrap: "normal" } : {}),
        wrap: p.wrap === "none" ? "off" : "soft", value: w.text, disabled: p.state === "disabled",
        onChange: (e) => { w._p.text = e.target.value; w._form._render(); },
      }));
    case "Checkbutton":
    case "Radiobutton":
      return h("label", Object.assign(base, { className: "tk tk-choice", style: dmsStyle(w) }),
        h("input", {
          type: w.kind === "Checkbutton" ? "checkbox" : "radio", name: p.group || undefined,
          checked: w.checked, disabled: !w.enabled,
          onChange: (e) => {
            w.checked = w.kind === "Checkbutton" ? e.target.checked : true;
            w._fire("command");
          },
        }),
        h("span", null, w.text));
    case "Listbox": {
      const multiple = p.selectmode === "multiple" || p.selectmode === "extended";
      return h("select", Object.assign(base, dmsKeys(w), {
        className: "tk", style: dmsStyle(w), size: 2, multiple,
        value: multiple ? w._multi.map(String) : (w._sel >= 0 ? String(w._sel) : ""),
        onChange: (e) => {
          const chosen = Array.from(e.target.selectedOptions, (o) => Number(o.value));
          w._multi = chosen;
          w._sel = chosen.length ? chosen[0] : -1;
          w._form._render();
          w._fire("select", dmsEvent(w, e));
        },
      }), w._items.map((item, i) => h("option", { key: i, value: String(i) }, item)));
    }
    case "Combobox": {
      if (p.state === "readonly" || p.state === "disabled") {
        return h("select", Object.assign(base, dmsKeys(w), {
          className: "tk", style: dmsStyle(w), disabled: p.state === "disabled",
          value: w._sel >= 0 ? String(w._sel) : "",
          onChange: (e) => { w.index = Number(e.target.value); w._fire("select", dmsEvent(w, e)); },
        }), [w._sel < 0 ? h("option", { key: "none", value: "" }, w.text) : null,
          ...w._items.map((item, i) => h("option", { key: i, value: String(i) }, item))]);
      }
      const list = w.name + "-items";
      return h(React.Fragment, { key },
        h("input", Object.assign(base, dmsKeys(w), {
          key: "input", className: "tk", style: dmsStyle(w), list, value: w.text,
          onChange: (e) => {
            w._p.text = e.target.value;
            const i = w._items.indexOf(e.target.value);
            w._sel = i;
            w._form._render();
            if (i >= 0) w._fire("select", dmsEvent(w, e));
          },
        })),
        h("datalist", { key: "list", id: list }, w._items.map((item, i) => h("option", { key: i, value: item }))));
    }
    case "Scale": {
      const vertical = p.orient === "vertical";
      return h("div", Object.assign(base, { className: "tk tk-scale" + (vertical ? " tk-vertical" : ""), style: dmsStyle(w) }),
        p.label ? h("span", null, p.label) : null,
        h("input", {
          type: "range", min: p.from, max: p.to, step: p.resolution || 1, value: w.value, disabled: !w.enabled,
          onChange: (e) => { w._p.value = Number(e.target.value); w._form._render(); w._fire("command", w._p.value); },
        }),
        p.showvalue !== false ? h("output", null, String(w.value)) : null);
    }
    case "Progressbar": {
      const running = p.mode === "indeterminate" && p.running;
      return h("progress", Object.assign(base, {
        className: "tk tk-progress", style: dmsStyle(w),
        max: w.maximum, value: p.mode === "indeterminate" ? (running ? undefined : 0) : w.value,
      }));
    }
    case "Frame": {
      const border = p.bd > 0 ? { borderWidth: p.bd, borderStyle: "solid", borderColor: "#8a8f98" } : {};
      return h("div", Object.assign(base, { className: "tk tk-frame", style: dmsStyle(w, border) }),
        dmsChildren(w._form, w.name));
    }
    case "PageControl": {
      const active = w.page;
      return h("div", Object.assign(base, { className: "tk tk-pages", style: dmsStyle(w) }),
        h("div", { className: "tk-tabs" }, w.pages.map((title, i) => h("button", {
          key: i, type: "button", className: "tk-tab" + (i === active ? " tk-on" : ""),
          onClick: () => { if (i !== active) w.page = i; },
        }, title))),
        w.pages.map((title, i) => h("div", { key: i, className: "tk-page", hidden: i !== active },
          dmsChildren(w._form, w.name, i))));
    }
    case "Treeview": {
      const cols = w.columns;
      return h("div", Object.assign(base, { className: "tk tk-grid", style: dmsStyle(w) }),
        h("table", null,
          h("thead", null, h("tr", null, cols.map((c) => h("th", { key: c.field, style: c.width ? { width: c.width } : undefined }, c.title)))),
          h("tbody", null, w._rows.map((row, i) => h("tr", {
            key: i, className: i === w._sel ? "tk-chosen" : undefined,
            onClick: (e) => { w._sel = i; w._form._render(); w._fire("select", dmsEvent(w, e)); },
          }, cols.map((c, j) => {
            const v = w._cell(row, c, j);
            return h("td", { key: c.field }, v === undefined || v === null ? "" : String(v));
          }))))));
    }
    case "StatusBar":
      return h("div", Object.assign(base, { className: "tk tk-status", style: dmsStyle(w) }),
        w.icon ? h("span", { className: "tk-sicon" }, w.icon) : null, h("span", null, w.text));
    case "HtmlView": {
      const full = !!p.full_page;
      return h("div", Object.assign(base, {
        className: "tk tk-html" + (full ? " tk-html-full" : ""), style: full ? undefined : dmsStyle(w),
        dangerouslySetInnerHTML: { __html: w.html },
        onClick: (e) => dmsHtmlClick(w, e),
        onSubmit: (e) => dmsHtmlSubmit(w, e),
      }));
    }
    case "Image": {
      const fit = { none: "none", contain: "contain", cover: "cover", stretch: "fill" }[p.fit || "contain"];
      const src = w.file ? DMS_HOST.imageUrl(w.file) : undefined;
      return h("img", Object.assign(base, {
        className: "tk tk-image", style: dmsStyle(w, { objectFit: fit, border: p.border ? "1px solid #8a8f98" : undefined }),
        src, alt: "",
      }));
    }
    default:
      return null;
  }
}

function DmsView({ form }) {
  const [, setTick] = React.useState(0);
  React.useEffect(() => {
    form._listener = () => setTick((t) => t + 1);
    return () => { form._listener = null; };
  }, [form]);
  const full = form._widgets.find((w) => w.kind === "HtmlView" && !w.parent && w._p.full_page);
  return h(React.Fragment, null,
    full
      ? h("main", { id: "tk-form", className: "tk-full" }, dmsWidget(full))
      : h("main", {
        id: "tk-form", className: "tk-form",
        style: { width: form._options.width, height: form._options.height, background: form._bg },
      }, dmsChildren(form, null)),
    form._toast ? h("div", { id: "tk-toast" }, form._toast) : null);
}

/** Crea la ventana de la clase del usuario y la pinta. */
function dmsStart(FormClass) {
  const form = new FormClass();
  window.dmsForm = form;
  const menu = form._widgets.find((w) => w.kind === "Menu");
  DMS_HOST.menu(menu ? menu._extra.tree || [] : null, (path) => { if (menu) menu._fire("command", path); });
  const events = form._formEvents;
  if (events.key) document.addEventListener("keydown", (e) => form._call(events.key, dmsEvent(null, e)));
  if (events.resize) window.addEventListener("resize", () => form._call(events.resize, { width: innerWidth, height: innerHeight }));
  if (events.close) window.addEventListener("beforeunload", () => form._call(events.close));
  createRoot(document.getElementById("root")).render(h(DmsView, { form }));
  for (const w of form._widgets) {
    if (w.kind === "Timer" && w._p.enabled !== false) w.start();
  }
  if (events.create) form._call(events.create);
  setTimeout(() => DMS_HOST.ready(), 50);
  return form;
}
''';

/// DMS_HOST de Electron: Node en la ventana (require, fs) y el proceso
/// principal por IPC (diálogos, menú nativo).
const tkElectronHostJs = r'''"use strict";
// Generated by DMarlon Studio. Do not edit.
(function () {
  const path = require("path");
  const url = require("url");
  const fs = require("fs");
  const { ipcRenderer, shell } = require("electron");

  function need(name) {
    try {
      return require(name);
    } catch (error) {
      const dir = process.env.DMSTUDIO_NODE_MODULES;
      if (!dir) throw error;
      return require(path.join(dir, name));
    }
  }

  const key = (k) => "dms:" + k;
  const storage = {
    async get(k, fallback) {
      const v = localStorage.getItem(key(k));
      return v === null ? fallback : JSON.parse(v);
    },
    async set(k, value) { localStorage.setItem(key(k), JSON.stringify(value)); },
    async remove(k) { localStorage.removeItem(key(k)); },
  };

  window.DMS_HOST = {
    kind: "electron",
    need,
    imageUrl: (file) => url.pathToFileURL(path.resolve(process.cwd(), file)).href,
    dialog: (kind, options) => ipcRenderer.invoke("dms-dialog", kind, options),
    readText: (file) => fs.readFileSync(file, "utf8"),
    writeText: (file, text) => fs.writeFileSync(file, text, "utf8"),
    alert: (text, title) => alert(title ? title + "\n\n" + text : text),
    menu: (tree, onClick) => {
      ipcRenderer.send("dms-menu", tree);
      ipcRenderer.on("dms-menu-click", (_e, item) => onClick(item));
    },
    ready: () => ipcRenderer.send("dms-ready"),
    onGo: (fn) => ipcRenderer.once("dms-go", fn),
    storage,
    currentTab: async () => ({ id: 0, url: location.href, title: document.title }),
    openTab: (address) => shell.openExternal(address),
    runInPage: async () => null,
    badge: () => {},
  };
})();
''';

/// El proceso principal de Electron: la ventana del tamaño del diseño, el
/// menú nativo, los diálogos de abrir y guardar, y la salida de la consola
/// de la ventana (para el panel de salida del estudio).
const tkElectronMainJs = r'''"use strict";
// Generated by DMarlon Studio. Do not edit.
process.env.ELECTRON_DISABLE_SECURITY_WARNINGS = "true";
const { app, BrowserWindow, Menu, dialog, ipcMain } = require("electron");
const fs = require("fs");
const path = require("path");
const WINDOW = require("./window.json");

const debug = process.env.DMSTUDIO_DEVTOOLS === "1";
const testScript = process.env.DMSTUDIO_ELECTRON_TEST || "";
let win = null;

function out(text) {
  process.stdout.write(String(text) + "\n");
}

function create() {
  const options = {
    width: WINDOW.width,
    height: WINDOW.height,
    useContentSize: true,
    title: WINDOW.title,
    backgroundColor: WINDOW.bg,
    resizable: WINDOW.resizable,
    alwaysOnTop: WINDOW.topmost,
    show: !testScript,
    webPreferences: { nodeIntegration: true, contextIsolation: false, sandbox: false },
  };
  if (WINDOW.position === "manual") {
    options.x = WINDOW.left;
    options.y = WINDOW.top;
  } else if (WINDOW.position === "center") {
    options.center = true;
  }
  win = new BrowserWindow(options);
  win.webContents.on("console-message", (...args) => {
    const e = args[0] && args[0].message !== undefined ? args[0] : { level: args[1], message: args[2], lineNumber: args[3], sourceId: args[4] };
    const level = typeof e.level === "number" ? ["log", "info", "warning", "error"][e.level] || "log" : e.level;
    if (/React DevTools|react-devtools/.test(String(e.message))) return;
    const where = e.sourceId ? path.basename(String(e.sourceId)) + ":" + e.lineNumber : "";
    if (level === "error" || level === "warning") out((where ? "[" + where + "] " : "") + e.message);
    else out(e.message);
  });
  win.loadFile(path.join(__dirname, "index.html"));
  win.webContents.on("did-finish-load", () => {
    if (debug) {
      win.webContents.once("devtools-opened", () => setTimeout(() => win.webContents.send("dms-go"), 400));
      win.webContents.openDevTools({ mode: "detach" });
    } else {
      win.webContents.send("dms-go");
    }
  });
}

function menuItems(items) {
  return items.map((item) => {
    if (item.separator) return { type: "separator" };
    if (item.items && item.items.length) return { label: item.label, submenu: menuItems(item.items) };
    return { label: item.label, click: () => win && win.webContents.send("dms-menu-click", item.path) };
  });
}

ipcMain.on("dms-menu", (_e, tree) => {
  const mac = process.platform === "darwin";
  const template = [];
  if (mac) template.push({ role: "appMenu" });
  if (tree && tree.length) {
    template.push(...menuItems(tree));
    if (mac) template.splice(1, 0, { role: "editMenu" });
  } else if (mac) {
    template.push({ role: "editMenu" }, { role: "windowMenu" });
  }
  if (template.length) {
    Menu.setApplicationMenu(Menu.buildFromTemplate(template));
  } else {
    Menu.setApplicationMenu(null);
  }
});

ipcMain.handle("dms-dialog", async (_e, kind, opts) => {
  const filters = (opts.filters || []).map((f) => ({ name: f.name, extensions: f.extensions }));
  if (kind === "save") {
    const r = await dialog.showSaveDialog(win, {
      title: opts.title || undefined,
      defaultPath: opts.filename ? path.join(opts.initialdir || "", opts.filename) : opts.initialdir || undefined,
      filters,
    });
    return r.canceled ? null : r.filePath;
  }
  const r = await dialog.showOpenDialog(win, {
    title: opts.title || undefined,
    defaultPath: opts.initialdir || undefined,
    filters,
    properties: opts.multiple ? ["openFile", "multiSelections"] : ["openFile"],
  });
  if (r.canceled || !r.filePaths.length) return null;
  return opts.multiple ? r.filePaths : r.filePaths[0];
});

ipcMain.on("dms-ready", async () => {
  if (!testScript) return;
  try {
    const result = await win.webContents.executeJavaScript(fs.readFileSync(testScript, "utf8"));
    out("DMSTUDIO_TEST " + JSON.stringify(result));
    app.exit(0);
  } catch (error) {
    out("DMSTUDIO_TEST_ERROR " + (error && error.stack ? error.stack : error));
    app.exit(1);
  }
});

app.whenReady().then(create);
app.on("window-all-closed", () => app.quit());
''';

